//! `TopSurface.h/.cpp` (ironing is implemented together with the layer planning code).

use crate::geometry::Shape;
use crate::slice_data_storage::SliceMeshStorage;

#[derive(Clone, Debug, Default)]
pub struct TopSurface {
    /// The areas of top surface, for each layer.
    pub areas: Shape,
}

impl TopSurface {
    pub fn new() -> Self {
        TopSurface { areas: Shape::default() }
    }

    /// Generate new top surface for a specific layer.
    ///
    /// The surface will be generated by subtracting the layer above from the
    /// current layer. Anything that is leftover is then part of the top surface
    /// (since there is nothing above it).
    pub fn set_areas_from_mesh_and_layer_number(&mut self, mesh: &SliceMeshStorage, layer_number: usize) {
        // The top surface is all parts of the mesh where there's no mesh above it, so find the layer above it first.
        let mut mesh_above = Shape::default();
        if layer_number < mesh.layers.len() - 1 {
            mesh_above = mesh.layers[layer_number + 1].get_outlines(false);
        } // If this is the top-most layer, mesh_above stays empty.

        if mesh.settings().get_bool("magic_spiralize") {
            // when spiralizing, the model is often solid so it's no good trying to determine if there is air above or not
            // in this situation, just iron the topmost of the bottom layers
            if layer_number == mesh.settings().get_usize("initial_bottom_layers").wrapping_sub(1) {
                self.areas = mesh.layers[layer_number].get_outlines(false);
            }
        } else {
            self.areas = mesh.layers[layer_number].get_outlines(false).difference(&mesh_above);
        }
    }
}
